import functools

def log_calls(func):
    @functools.wraps(func)          # keep the original name and docstring
    def wrapper(*args):
        result = func(*args)
        print(f"log: {func.__name__} -> {result}")
        return result
    return wrapper

def require_role(role):             # a decorator with arguments
    def decorator(func):
        @functools.wraps(func)
        def wrapper(user, *args):
            if role not in user["roles"]:
                return f"denied: {user['name']} is not {role}"
            return func(user, *args)
        return wrapper
    return decorator

@log_calls                          # decorators stack: bottom one first
@require_role("admin")
def refund(user, amount):
    return f"{user['name']} refunded {amount:.2f} EUR"

ana = {"name": "Ana", "roles": ["admin", "sales"]}
luis = {"name": "Luis", "roles": ["sales"]}

print(refund(ana, 30))
print(refund(luis, 30))
print("Name kept:", refund.__name__)

class Paginator:
    """Iterates over a list of results, one page at a time."""

    def __init__(self, items, page_size):
        self.items = items
        self.page_size = page_size
        self.start = 0

    def __iter__(self):
        return self                   # this object is its own iterator

    def __next__(self):
        if self.start >= len(self.items):
            raise StopIteration       # tells for that there is no more
        page = self.items[self.start:self.start + self.page_size]
        self.start += self.page_size
        return page

orders = [f"#{n}" for n in range(1001, 1011)]

# What a for loop does behind the scenes: iter() and next()
it = iter(["ok", "fail"])
print(next(it), next(it))
try:
    next(it)
except StopIteration:
    print("StopIteration: the list is used up")

for number, page in enumerate(Paginator(orders, 4), start=1):
    print(f"Page {number}: {page}")

# Any function that loops accepts our iterator
print("Pages:", len(list(Paginator(orders, 3))))

class Player:
    """A player in a small role-playing game."""
    max_health = 100                  # class attribute: shared by all

    def __init__(self, name, attack):
        self.name = name              # instance attributes: one per object
        self.attack = attack
        self.health = Player.max_health
        self.inventory = []

    def hit(self, other):
        other.health = max(0, other.health - self.attack)
        print(f"{self.name} hits {other.name}: {other.health} HP left")

    def pick_up(self, item):
        self.inventory.append(item)

    @property
    def alive(self):                  # used like an attribute, no ()
        return self.health > 0

    def __str__(self):
        return f"{self.name} ({self.health}/{self.max_health} HP)"

hero = Player("Aria", attack=35)
orc = Player("Grok", attack=20)
hero.pick_up("potion")
while orc.alive:
    hero.hit(orc)
print(hero, "| inventory:", hero.inventory)
print(orc, "| alive:", orc.alive)
print("Same class:", type(hero) is type(orc), "| same object:", hero is orc)

class Money:
    def __init__(self, cents, currency="EUR"):
        self.cents = cents
        self.currency = currency

    def __repr__(self):               # how it prints, also inside lists
        return f"{self.cents / 100:.2f} {self.currency}"

    def __eq__(self, other):          # ==
        return (self.cents, self.currency) == (other.cents, other.currency)

    def __lt__(self, other):          # < (and so sorted, min, max)
        return self.cents < other.cents

    def __add__(self, other):         # +
        if self.currency != other.currency:
            raise ValueError("cannot add different currencies")
        return Money(self.cents + other.cents, self.currency)

class Cart:
    def __init__(self, *prices):
        self.prices = list(prices)
    def __len__(self):                # len(cart)
        return len(self.prices)

cart = Cart(Money(1999), Money(450), Money(12000))
print("Items:", len(cart), cart.prices)
print("Total:", sum(cart.prices, Money(0)))
print("Sorted:", sorted(cart.prices))
print("Equal:", Money(450) == Money(450), "| less:", Money(450) < Money(1999))
try:
    Money(100) + Money(100, "USD")
except ValueError as error:
    print("Error:", error)

from typing import Protocol, runtime_checkable

type Euros = float                    # a type alias (Python 3.12)

@runtime_checkable
class Priced(Protocol):               # any class with price() fits
    def price(self) -> Euros: ...

class Book:                           # no inheritance from Priced needed
    def __init__(self, title: str, cost: Euros) -> None:
        self.title = title
        self.cost = cost

    def price(self) -> Euros:
        return self.cost

class Subscription:
    def __init__(self, months: int) -> None:
        self.months = months

    def price(self) -> Euros:
        return self.months * 7.99

def basket_total(items: list[Priced], vat: float = 0.04) -> Euros:
    return round(sum(item.price() for item in items) * (1 + vat), 2)

def first[T](items: list[T], default: T) -> T:    # a generic function
    return items[0] if items else default

basket: list[Priced] = [Book("Dune", 11.5), Subscription(3)]
print("Total:", basket_total(basket))
print("Is Priced:", isinstance(basket[1], Priced), isinstance("Dune", Priced))
print("First:", first(["INV-1", "INV-2"], "none"), "|", first([], 0))
print("Not enforced:", repr(Subscription("3").months))   # runs anyway

from dataclasses import dataclass

class OutOfStock(Exception): pass     # our own error for this program

@dataclass
class Product:
    sku: str
    price: float
    stock: int = 0

class Inventory:
    def __init__(self, *products):
        self.products = {p.sku: p for p in products}
    def sell(self, sku, qty):
        product = self.products[sku]          # KeyError if the SKU is unknown
        if qty > product.stock:
            raise OutOfStock(f"only {product.stock} x {sku} left")
        product.stock -= qty
        return qty * product.price

    def value(self):
        return sum(p.price * p.stock for p in self.products.values())

shop = Inventory(Product("CHAIR", 49.5, 10), Product("TABLE", 230.0, 2))
assert shop.value() == 955.0                  # a test: stops here if False
assert shop.sell("CHAIR", 4) == 198.0
assert shop.products["CHAIR"].stock == 6, "stock was not updated"
try:
    shop.sell("TABLE", 5)
    assert False, "OutOfStock expected"
except OutOfStock as error:
    print("Expected error:", error)
print(shop.products["CHAIR"], "| value:", shop.value())
print("All tests passed")
